from openpyxl import load_workbook
from pathlib import Path
import re
path=Path('/root/output/result.xlsx')
wb=load_workbook(path, data_only=False)
ws=wb['Task']
errors=[]
expected_sheets=['Task','Data']
print('Output exists:', path.exists(), 'size:', path.stat().st_size)
print('Sheets:', wb.sheetnames)
if wb.sheetnames != expected_sheets:
    errors.append(f'Unexpected sheets: {wb.sheetnames}')

sample=['H12','L17','H19','L24','H26','L31','H35','L40','H42','L47','H50','L50']
print('\nSample formulas:')
for coord in sample:
    v=ws[coord].value
    print(coord, repr(v))
    if not (isinstance(v,str) and v.startswith('=')):
        errors.append(f'{coord} expected formula, got {v!r}')

# Full expected formula checks
for r in list(range(12,18))+list(range(19,25))+list(range(26,32)):
    for c in range(8,13):
        col=ws.cell(10,c).coordinate[:-2] if False else None
        from openpyxl.utils import get_column_letter
        letter=get_column_letter(c)
        exp=f'=INDEX(Data!$H$21:$L$38, MATCH($D{r}, Data!$D$21:$D$38, 0), MATCH({letter}$10, Data!$H$4:$L$4, 0))'
        v=ws.cell(r,c).value
        if v != exp:
            errors.append(f'{ws.cell(r,c).coordinate} mismatch: {v!r} != {exp!r}')

from openpyxl.utils import get_column_letter
for idx,r in enumerate(range(35,41)):
    for c in range(8,13):
        letter=get_column_letter(c)
        exp=f'=({letter}{12+idx}-{letter}{19+idx})/{letter}{26+idx}*100'
        v=ws.cell(r,c).value
        if v != exp:
            errors.append(f'{ws.cell(r,c).coordinate} mismatch: {v!r} != {exp!r}')

summary = {42:'MIN',43:'MAX',44:'MEDIAN',45:'AVERAGE',46:'P25',47:'P75'}
for r,kind in summary.items():
    for c in range(8,13):
        letter=get_column_letter(c)
        rng=f'{letter}35:{letter}40'
        if kind == 'P25': exp=f'=PERCENTILE({rng},0.25)'
        elif kind == 'P75': exp=f'=PERCENTILE({rng},0.75)'
        else: exp=f'={kind}({rng})'
        v=ws.cell(r,c).value
        if v != exp:
            errors.append(f'{ws.cell(r,c).coordinate} mismatch: {v!r} != {exp!r}')

for c in range(8,13):
    letter=get_column_letter(c)
    exp=f'=SUMPRODUCT({letter}35:{letter}40,{letter}26:{letter}31)/SUM({letter}26:{letter}31)'
    v=ws.cell(50,c).value
    if v != exp:
        errors.append(f'{ws.cell(50,c).coordinate} mismatch: {v!r} != {exp!r}')

# Confirm no empty/plain values in expected formula ranges.
checked=0
for rangestr in ['H12:L17','H19:L24','H26:L31','H35:L40','H42:L47','H50:L50']:
    for row in ws[rangestr]:
        for cell in row:
            checked += 1
            v=cell.value
            if not (isinstance(v,str) and v.startswith('=')):
                errors.append(f'{cell.coordinate} not formula: {v!r}')
print('\nFormula cells checked:', checked)

# Confirm percentile compatibility.
percentile_formulas=[]
bad_percentile=[]
for row in ws.iter_rows():
    for cell in row:
        v=cell.value
        if isinstance(v,str) and 'PERCENTILE' in v.upper():
            percentile_formulas.append((cell.coordinate, v))
            if 'PERCENTILE.INC' in v.upper() or 'PERCENTILE.EXC' in v.upper():
                bad_percentile.append((cell.coordinate, v))
print('Percentile formulas:', percentile_formulas)
if bad_percentile:
    errors.append(f'Bad percentile formulas found: {bad_percentile}')

# Data-only open for cached values not required, but ensure file opens.
wbv=load_workbook(path, data_only=True)
print('Data-only workbook opens; sheets:', wbv.sheetnames)

if errors:
    print('\nVERIFICATION FAILED')
    for e in errors[:50]: print('ERROR:', e)
    print('error_count', len(errors))
    raise SystemExit(1)
print('\nVERIFICATION PASSED')
